-- Transaction controls linking projects to procurement, construction and finance.
create table if not exists public.purchase_orders (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid references public.property_projects(id) on delete set null,supplier_id uuid not null references public.business_partners(id),po_no text not null,po_date date not null default current_date,expected_date date,status text not null default 'DRAFT',subtotal numeric not null default 0,tax_amount numeric not null default 0,total_amount numeric not null default 0,created_by uuid references public.profiles(id),approved_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,po_no));
create table if not exists public.purchase_order_lines (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),purchase_order_id uuid not null references public.purchase_orders(id) on delete cascade,item_id uuid references public.inventory_items(id) on delete set null,description text not null,quantity numeric not null check(quantity>0),unit_of_measure text,unit_price numeric not null default 0,tax_rate numeric not null default 0,line_total numeric not null default 0,project_id uuid references public.property_projects(id) on delete set null);
create table if not exists public.project_work_packages (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null references public.property_projects(id) on delete cascade,code text not null,name text not null,discipline text,contractor_id uuid references public.business_partners(id) on delete set null,budget_amount numeric not null default 0,planned_start date,planned_end date,actual_start date,actual_end date,progress_pct numeric not null default 0,status text not null default 'PLANNED',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(project_id,code));
create table if not exists public.accounts_payable (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid references public.property_projects(id) on delete set null,supplier_id uuid not null references public.business_partners(id),invoice_no text not null,invoice_date date not null,due_date date,amount numeric not null default 0,paid_amount numeric not null default 0,status text not null default 'OPEN',source_po_id uuid references public.purchase_orders(id) on delete set null,created_at timestamptz not null default now(),unique(organization_id,invoice_no));
create table if not exists public.accounts_receivable (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid references public.property_projects(id) on delete set null,customer_id uuid not null references public.customers(id),invoice_no text not null,invoice_date date not null,due_date date,amount numeric not null default 0,paid_amount numeric not null default 0,status text not null default 'OPEN',reservation_id uuid references public.sales_reservations(id) on delete set null,created_at timestamptz not null default now(),unique(organization_id,invoice_no));
create table if not exists public.cash_accounts (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),account_code text not null,account_name text not null,account_type text not null check(account_type in ('CASH','BANK','PETTY_CASH')),currency text not null default 'IDR',opening_balance numeric not null default 0,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,account_code));
create table if not exists public.cash_transactions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),cash_account_id uuid not null references public.cash_accounts(id),project_id uuid references public.property_projects(id) on delete set null,transaction_date date not null default current_date,transaction_type text not null,amount numeric not null check(amount>0),reference_no text,description text,counterparty_id uuid references public.business_partners(id) on delete set null,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.project_cost_commitments (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null references public.property_projects(id) on delete cascade,cost_category text not null,reference_type text not null,reference_id uuid,amount numeric not null default 0,status text not null default 'COMMITTED',created_at timestamptz not null default now());
create index if not exists idx_purchase_orders_project on public.purchase_orders(project_id,status); create index if not exists idx_purchase_orders_supplier on public.purchase_orders(supplier_id); create index if not exists idx_po_lines_item on public.purchase_order_lines(item_id); create index if not exists idx_work_packages_project on public.project_work_packages(project_id,status); create index if not exists idx_ap_project_due on public.accounts_payable(project_id,due_date); create index if not exists idx_ar_project_due on public.accounts_receivable(project_id,due_date); create index if not exists idx_cash_tx_account_date on public.cash_transactions(cash_account_id,transaction_date); create index if not exists idx_project_commitments_project on public.project_cost_commitments(project_id);
create or replace function public.enterprise_can_manage() returns boolean language sql stable security invoker set search_path=public as $$ select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.active and p.role in ('SUPER_ADMIN','DIRECTOR','EXECUTIVE','DEPARTMENT_HEAD','MANAGER') and p.organization_id=(select public.current_organization_id())) $$;
do $$ declare t text; begin foreach t in array array['purchase_orders','purchase_order_lines','project_work_packages','accounts_payable','accounts_receivable','cash_accounts','cash_transactions','project_cost_commitments'] loop execute format('alter table public.%I enable row level security',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); execute format('create policy %I_org_select on public.%I for select to authenticated using (organization_id=(select public.current_organization_id()))',t,t); execute format('create policy %I_manage on public.%I for all to authenticated using (organization_id=(select public.current_organization_id()) and (select public.enterprise_can_manage())) with check (organization_id=(select public.current_organization_id()) and (select public.enterprise_can_manage()))',t,t); end loop; end $$;
